function BookbindingScrewPressMaker.completeMaking(m) local q=1.0+(BookbindingScrewPressMaker.getQualityBonus()/100); if BookbindingScrewPressMaker.maker then q=q+(BookbindingScrewPressMaker.maker.skill/140) end; q=math.min(2.5,q); BookbindingScrewPressMaker.productStock[m.productType]=(BookbindingScrewPressMaker.productStock[m.productType] or 0)+m.quantity; BookbindingScrewPressMaker.totalProducts=BookbindingScrewPressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookbindingScrewPressMaker.maker then BookbindingScrewPressMaker.maker.itemsMade=BookbindingScrewPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookbindingScrewPressMaker.maker.skill=math.min(100,BookbindingScrewPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskalnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookbindingscrewpress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
